// Renders docs/report/the-price-of-exactness.md to a PDF next to it, as a paper: A4,
// Inter for text, JetBrains Mono for numbers, the benchmark's own SVG figures.
// The Markdown is generated by `cargo run -p bench -- story`; run that first.
//
//   node web/scripts/report-pdf.mjs
//   node web/scripts/report-pdf.mjs --preview out.png   # also a full-length screenshot

import { chromium } from "@playwright/test";
import { readFileSync, writeFileSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { marked } from "marked";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..", "..");
const reportDir = join(root, "docs", "report");
const source = join(reportDir, "the-price-of-exactness.md");
const target = join(reportDir, "the-price-of-exactness.pdf");
const fonts = join(here, "..", "node_modules", "@fontsource-variable");

const md = readFileSync(source, "utf8").replace(/^---\n[\s\S]*?\n---\n/, "");
const body = marked.parse(md);

const font = (family, file, style) =>
  `@font-face{font-family:"${family}";src:url("${pathToFileURL(join(fonts, file)).href}") format("woff2");font-weight:100 900;font-style:${style};}`;

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<base href="${pathToFileURL(reportDir + "/").href}">
<title>The Price of Exactness in Distributed Rate Limiting</title>
<style>
${font("Inter", "inter/files/inter-latin-wght-normal.woff2", "normal")}
${font("Inter", "inter/files/inter-latin-wght-italic.woff2", "italic")}
${font("JetBrains Mono", "jetbrains-mono/files/jetbrains-mono-latin-wght-normal.woff2", "normal")}
@page { size: A4; margin: 20mm 20mm 22mm; }
html { font-family: Inter, sans-serif; font-size: 9.6pt; line-height: 1.5; color: #16161a; }
body { margin: 0; }
h1 { font-size: 19pt; line-height: 1.2; margin: 0 0 4pt; letter-spacing: -0.02em; }
h1 + p { color: #55555c; margin-top: 0; }
h2 { font-size: 12.5pt; margin: 16pt 0 4pt; break-after: avoid; }
h3 { font-size: 10.5pt; margin: 12pt 0 3pt; break-after: avoid; }
p { margin: 0 0 7pt; text-align: justify; hyphens: auto; }
blockquote { margin: 10pt 0 14pt; padding: 8pt 12pt; background: #f2f2ee; border-left: 2px solid #16161a; }
blockquote p { margin: 0; }
code { font-family: "JetBrains Mono", monospace; font-size: 8.8pt; }
table { border-collapse: collapse; width: 100%; font-size: 8.8pt; margin: 6pt 0 2pt; break-inside: avoid; }
th, td { padding: 2.5pt 6pt 2.5pt 0; border-bottom: 0.5pt solid #d9d9d3; text-align: left; }
thead th { border-bottom: 0.8pt solid #16161a; font-weight: 600; }
td:not(:first-child), th:not(:first-child) { text-align: right; font-family: "JetBrains Mono", monospace; font-variant-numeric: tabular-nums; }
img { display: block; width: 74%; margin: 8pt auto 2pt; break-inside: avoid; }
p:has(> img) { text-align: center; break-inside: avoid; }
em { color: #33333a; }
p > em:only-child { display: block; font-size: 8.8pt; color: #55555c; margin-bottom: 4pt; }
ol, ul { margin: 0 0 7pt; padding-left: 16pt; }
li { margin-bottom: 2pt; }
a { color: inherit; }
</style></head>
<body>${body}</body></html>`;

const dir = mkdtempSync(join(tmpdir(), "ratelab-report-"));
const page = join(dir, "report.html");
writeFileSync(page, html);
const browser = await chromium.launch();
try {
  const tab = await browser.newPage();
  await tab.goto(pathToFileURL(page).href, { waitUntil: "networkidle" });
  await tab.evaluate(() => document.fonts.ready);
  const preview = process.argv.indexOf("--preview");
  if (preview > 0 && process.argv[preview + 1]) {
    await tab.emulateMedia({ media: "print" });
    await tab.setViewportSize({ width: 680, height: 1000 });
    await tab.screenshot({ path: process.argv[preview + 1], fullPage: true });
  }
  await tab.pdf({
    path: target,
    format: "A4",
    printBackground: true,
    displayHeaderFooter: true,
    headerTemplate: "<span></span>",
    footerTemplate:
      '<div style="font-family:Helvetica,Arial,sans-serif;font-size:7.5pt;color:#777;width:100%;padding:0 20mm;display:flex;justify-content:space-between"><span>The Price of Exactness in Distributed Rate Limiting</span><span><span class="pageNumber"></span> / <span class="totalPages"></span></span></div>',
  });
  console.log(`wrote ${target}`);
} finally {
  await browser.close();
  rmSync(dir, { recursive: true, force: true });
}
